4: 
5: export interface QuoteRequest {
6:   lines: readonly CartLine[];
7:   promotionCode?: string;
8: }
9: 
10: export class CartPricing {
11:   constructor(private readonly catalog: Catalog) {}
12: 
13:   quote(request: QuoteRequest): CartQuote {
14:     const lines: PricedLine[] = [];
15:     let subtotalCents = 0;
16:     let eligibleSubtotalCents = 0;
17:     for (const line of request.lines) {
18:       validateLine(line);
19:       const product = this.catalog.product(line.sku);
20:       const lineCents = addCents(0, product.unitCents * line.quantity);
21:       subtotalCents = addCents(subtotalCents, lineCents);
22:       if (product.promotionEligible) {
23:         eligibleSubtotalCents = addCents(eligibleSubtotalCents, lineCents);
24:       }
25:       lines.push({
26:         sku: line.sku,
27:         quantity: line.quantity,
28:         unitCents: product.unitCents,
29:         subtotalCents: lineCents,
30:       });
31:     }
32:     const promotion = request.promotionCode === undefined
33:       ? undefined : this.catalog.promotion(request.promotionCode);
34:     let discountCents = 0;
35:     let appliedCode: string | null = null;
36:     if (promotion && eligibleSubtotalCents >= promotion.minimumEligibleCents) {
37:       discountCents = promotionDiscount(eligibleSubtotalCents, promotion);
38:       if (discountCents > 0) appliedCode = promotion.code;
39:     }
40:     return {
41:       lines,
42:       subtotalCents,
43:       eligibleSubtotalCents,
44:       discountCents,
45:       totalCents: subtotalCents - discountCents,
46:       appliedCode,
47:     };
48:   }
49: }

