1: import type { CarrierRate, DeliveryOption, Parcel } from './model.js';
2: 
3: export function validateParcel(parcel: Parcel): void {
4:   if (!Number.isSafeInteger(parcel.weightGrams) || parcel.weightGrams <= 0) {
5:     throw new RangeError('Weight must be a positive integer');
6:   }
7:   if (!parcel.destination.trim()) {
8:     throw new RangeError('Destination is required');
9:   }
10: }
11: 
12: // Carrier payloads are untrusted, even when the adapter has static types.
13: export function isUsableRate(rate: CarrierRate): boolean {
14:   return typeof rate.service === 'string' && rate.service.trim().length > 0
15:     && Number.isSafeInteger(rate.amountCents) && rate.amountCents >= 0
16:     && Number.isSafeInteger(rate.days) && rate.days >= 1;
17: }
18: 
19: export function compareOptions(a: DeliveryOption, b: DeliveryOption): number {
20:   return a.amountCents - b.amountCents
21:     || a.days - b.days
22:     || a.carrierId.localeCompare(b.carrierId)
23:     || a.service.localeCompare(b.service);
24: }
25: 
26: export function copyParcel(parcel: Parcel): Parcel {
27:   return { weightGrams: parcel.weightGrams, destination: parcel.destination };
28: }
29: 
30: export function describeOption(option: DeliveryOption): string {
31:   const unit = option.days === 1 ? 'day' : 'days';
32:   return `${option.carrierId} ${option.service}: ${option.days} ${unit}`;
33: }

